<?php
/** @var array $forms @var array|null $editing @var \Core\Security\Csrf $csrf @var string $basePath */
$editingFields = $editing ? (json_decode((string) $editing['fields_json'], true) ?: []) : [];
$activeCount = count(array_filter($forms, static fn (array $form): bool => (bool) $form['active']));
$submissionCount = array_sum(array_map(static fn (array $form): int => (int) $form['submission_count'], $forms));
?>
<section class="status-strip" aria-label="Forms summary">
  <div class="status-chip"><strong><?= count($forms) ?></strong><span>Total forms</span></div>
  <div class="status-chip"><strong><?= $activeCount ?></strong><span>Active</span></div>
  <a class="status-chip" href="<?= e_attr($basePath) ?>/admin/forms/submissions"><strong><?= $submissionCount ?></strong><span>Submissions</span></a>
</section>

<div class="section-grid wide-main">
  <div class="card">
    <div class="card-heading"><div><h2>Form library</h2><p class="card-subtitle">Reusable forms can be placed on any page with the visual composer’s Form block.</p></div><a class="btn" href="<?= e_attr($basePath) ?>/admin/forms/submissions">Open inbox</a></div>
    <?php if ($forms === []): ?><div class="empty-state"><strong>No forms yet</strong><span>Use the form builder to create your first enquiry, booking, or contact form.</span></div><?php else: ?>
    <table><thead><tr><th>Form</th><th>Status</th><th>Submissions</th><th>Actions</th></tr></thead><tbody>
    <?php foreach ($forms as $form): ?><tr>
      <td><strong><?= e($form['name']) ?></strong><br><span class="muted">Form ID <?= (int) $form['id'] ?></span></td>
      <td><span class="badge <?= $form['active'] ? 'ok' : 'neutral' ?>"><?= $form['active'] ? 'Active' : 'Archived' ?></span></td>
      <td><a href="<?= e_attr($basePath) ?>/admin/forms/submissions?form=<?= (int) $form['id'] ?>"><?= (int) $form['submission_count'] ?> entr<?= (int) $form['submission_count'] === 1 ? 'y' : 'ies' ?></a></td>
      <td><div class="button-row compact"><a class="btn small secondary" href="<?= e_attr($basePath) ?>/admin/forms?edit=<?= (int) $form['id'] ?>">Edit</a><a class="btn small secondary" href="<?= e_attr($basePath) ?>/admin/forms/submissions?form=<?= (int) $form['id'] ?>">Entries</a><?php if ($form['active']): ?><form method="post" action="<?= e_attr($basePath) ?>/admin/forms/<?= (int) $form['id'] ?>/archive"><?= $csrf->field() ?><button class="btn small danger" data-confirm="Archive this form? Existing submissions will be preserved.">Archive</button></form><?php endif; ?></div></td>
    </tr><?php endforeach; ?></tbody></table><?php endif; ?>
  </div>

  <aside class="help-panel"><h3>Publishing a form</h3><ol><li>Create and save the fields here.</li><li>Open the page in the visual composer.</li><li>Add a <strong>Form</strong> block and choose this form ID.</li></ol><p>Archived forms stop accepting new entries while keeping their submission history.</p></aside>
</div>

<div class="card" id="form-editor">
  <div class="card-heading"><div><h2><?= $editing ? 'Edit “' . e($editing['name']) . '”' : 'Create a form' ?></h2><p class="card-subtitle">Define what visitors see, where notifications go, and the confirmation they receive.</p></div><?php if ($editing): ?><a class="btn secondary" href="<?= e_attr($basePath) ?>/admin/forms#form-editor">Create another</a><?php endif; ?></div>
  <form method="post" action="<?= e_attr($basePath) ?>/admin/forms/save" data-busy-label="Saving form…">
    <?= $csrf->field() ?><input type="hidden" name="id" value="<?= (int) ($editing['id'] ?? 0) ?>"><input type="hidden" id="fields-json" name="fields_json" value="<?= e_attr(json_encode($editingFields, JSON_UNESCAPED_SLASHES)) ?>">
    <div class="inline-fields"><div><label for="form-name">Form name</label><input id="form-name" name="name" value="<?= e_attr($editing['name'] ?? '') ?>" placeholder="Request a quote" required></div><div><label for="form-recipient">Notification recipient</label><input id="form-recipient" type="email" name="recipient" value="<?= e_attr($editing['recipient'] ?? '') ?>" placeholder="hello@example.com"><small>Leave blank to store entries without email alerts.</small></div></div>
    <div class="inline-fields"><div><label for="form-subject">Email subject</label><input id="form-subject" name="subject" value="<?= e_attr($editing['subject'] ?? 'New website form submission') ?>"></div><div><label for="form-success">Success message</label><input id="form-success" name="success_message" value="<?= e_attr($editing['success_message'] ?? 'Thank you. Your message has been received.') ?>"></div></div>
    <input type="hidden" name="active" value="0"><label class="toggle-control"><span><strong>Accept submissions</strong><small>Turn this off to keep the form and its history without displaying it publicly.</small></span><input type="checkbox" name="active" value="1" <?= !isset($editing['active']) || $editing['active'] ? 'checked' : '' ?>><span class="toggle-track" aria-hidden="true"></span></label>
    <div class="builder-shell"><div class="card-heading"><div><h3>Form fields</h3><p class="card-subtitle">Arrange fields in the order visitors should complete them.</p></div><button type="button" class="btn secondary" id="add-field">Add field</button></div><div id="form-fields"></div><div id="form-fields-empty" class="empty-state"><strong>No fields added</strong><span>Add the first field to begin building this form.</span></div></div>
    <div class="action-bar"><span class="muted" id="field-count"></span><button class="btn">Save form</button></div>
  </form>
</div>
<script>
(()=>{const input=document.getElementById('fields-json'),list=document.getElementById('form-fields'),empty=document.getElementById('form-fields-empty'),count=document.getElementById('field-count');let fields=[];try{fields=JSON.parse(input.value||'[]');if(!Array.isArray(fields))fields=[]}catch(_){}const types={text:'Short text',email:'Email address',tel:'Phone number',number:'Number',date:'Date',textarea:'Long message',select:'Dropdown choice',checkbox:'Checkbox / consent'};const sync=()=>{input.value=JSON.stringify(fields);empty.hidden=fields.length>0;count.textContent=fields.length+' field'+(fields.length===1?'':'s')};const render=()=>{list.innerHTML='';fields.forEach((f,i)=>{const row=document.createElement('div');row.className='builder-block';row.innerHTML='<div class="builder-block-title"><strong>Field '+(i+1)+'</strong><span class="drag-hint">Use arrows to reorder</span></div><div class="builder-fields"><label>Label<input class="label" placeholder="Your name"></label><label>Field name<input class="name" placeholder="your_name"><small>Used in exports and emails.</small></label><label>Type<select class="type"></select></label><label class="field-options">Options<textarea class="options" rows="2" placeholder="One choice per line"></textarea></label><label class="choice-row compact"><input class="required" type="checkbox"><span>Required</span></label><div class="button-row"><button type="button" class="btn small secondary up" aria-label="Move field up">↑ Up</button><button type="button" class="btn small secondary down" aria-label="Move field down">↓ Down</button><button type="button" class="btn small danger remove">Remove</button></div></div>';Object.entries(types).forEach(([value,label])=>{const o=document.createElement('option');o.value=value;o.textContent=label;row.querySelector('.type').appendChild(o)});for(const k of ['label','name','type','options']){const el=row.querySelector('.'+k);el.value=Array.isArray(f[k])?f[k].join('\n'):(f[k]||'');el.oninput=()=>{f[k]=el.value;if(k==='type')row.querySelector('.field-options').hidden=el.value!=='select';sync()}}row.querySelector('.field-options').hidden=(f.type||'text')!=='select';row.querySelector('.required').checked=Boolean(f.required);row.querySelector('.required').onchange=e=>{f.required=e.target.checked;sync()};row.querySelector('.up').disabled=i===0;row.querySelector('.down').disabled=i===fields.length-1;row.querySelector('.up').onclick=()=>{if(i){[fields[i-1],fields[i]]=[fields[i],fields[i-1]];render()}};row.querySelector('.down').onclick=()=>{if(i<fields.length-1){[fields[i+1],fields[i]]=[fields[i],fields[i+1]];render()}};row.querySelector('.remove').onclick=()=>{if(confirm('Remove this field?')){fields.splice(i,1);render()}};list.appendChild(row)});sync()};document.getElementById('add-field').onclick=()=>{fields.push({label:'New field',name:'new_field_'+(fields.length+1),type:'text',required:false,options:''});render();list.lastElementChild?.scrollIntoView({behavior:'smooth',block:'center'})};render()})();
</script>
